namespace uk.osric.asp.Runtime;

using uk.osric.asp.Core.Compilation;

/// <summary>One library a page may name: the key it is stored under and the unit it contributes.</summary>
/// <param name="Key">The library's canonical key, which is how a diagnostic names it.</param>
/// <param name="Source">
/// The declarations the library contributes, generated by
/// <see cref="TemplateSourceGenerator.GenerateLibrary(string)"/> rather than as a page.
/// </param>
public sealed record LibrarySource(string Key, GeneratedSource Source);
